USE `accounting_dep_db`;
SET FOREIGN_KEY_CHECKS = 0;

-- 1. Ensure latest columns exist in JournalVoucher and FOPMaster
ALTER TABLE `JournalVoucher` ADD COLUMN IF NOT EXISTS `source_misc_ticket_id` INT NULL;
ALTER TABLE `FOPMaster` ADD COLUMN IF NOT EXISTS `effective_from` DATE NULL;

-- 2. Drop and Re-create complete Misc_Transactions table with all columns
DROP TABLE IF EXISTS `Misc_Transactions`;

CREATE TABLE `Misc_Transactions` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `company_id` INT NOT NULL,
  `branch_name` VARCHAR(100) NULL,
  `invoice_number` VARCHAR(20) NOT NULL,
  `invoice_date` DATE NOT NULL,
  `invoice_type` VARCHAR(100) NULL,
  `status` VARCHAR(20) NOT NULL DEFAULT 'Confirmed',
  `user_name` VARCHAR(100) NULL,
  `reference` VARCHAR(30) NOT NULL,
  `ref_date` DATE NULL,
  `payment_mode` VARCHAR(20) NULL,
  `payment_gateway_ref` VARCHAR(60) NULL,
  `currency` VARCHAR(5) NOT NULL DEFAULT 'INR',
  `description` LONGTEXT NULL,
  `base_amount` DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  `markup` DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  `service_fee` DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  `supp_markup` DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  `supp_service_fee` DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  `total_billed` DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `customer_ledger_id` INT NOT NULL,
  `supplier_ledger_id` INT NOT NULL,
  `other_taxes` DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  KEY `idx_misc_company` (`company_id`),
  KEY `idx_misc_customer` (`customer_ledger_id`),
  KEY `idx_misc_supplier` (`supplier_ledger_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `Misc_Transactions` (`id`, `company_id`, `branch_name`, `invoice_number`, `invoice_date`, `invoice_type`, `status`, `user_name`, `reference`, `ref_date`, `payment_mode`, `payment_gateway_ref`, `currency`, `description`, `base_amount`, `markup`, `service_fee`, `supp_markup`, `supp_service_fee`, `total_billed`, `created_at`, `updated_at`, `customer_ledger_id`, `supplier_ledger_id`, `other_taxes`) VALUES (7, 1, NULL, '1', '2026-10-16', 'Miscellaneous', 'Confirmed', 'Rahul Mehta', 'TEST', '2026-10-16', 'Top-up', NULL, 'INR', 'Visa Manual Accounting', 100.00, 70.00, 40.00, 50.00, 20.00, 310.80, '2026-10-16 10:34:35', '2026-10-16 10:34:35', 1089, 1068, 20.00);

